def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = min(budget, DAILY_SALARY * 0.25)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.6)
        return float(max(0.0, safe_bid))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 300:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.3
    if no_water_days >= 2:
        danger += 0.35
    elif no_water_days == 1:
        danger += 0.15
    danger += scarcity * 0.25
    if day >= 8:
        danger += 0.1

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif supply <= 17:
        bid = max(DAILY_SALARY * 0.38 + scarcity * 18.0, avg_prev * 0.55 + 2.0)
    else:
        bid = DAILY_SALARY * 0.22 + scarcity * 10.0

    if highest_prev >= 120:
        if danger < 0.45:
            bid = min(bid, DAILY_SALARY * 0.28)
        else:
            bid = max(bid, DAILY_SALARY * 0.72)
    elif highest_prev >= 60:
        if danger < 0.35:
            bid = min(bid, DAILY_SALARY * 0.32)
        else:
            bid = max(bid, highest_prev * 0.78 + 2.0)
    elif highest_prev > 0:
        bid = max(bid, min(DAILY_SALARY * 0.58, highest_prev + 1.5))

    if rich_opp >= 2 and danger < 0.4:
        bid = min(bid, DAILY_SALARY * 0.26)

    if urgent_opp >= 1 and danger >= 0.4:
        bid = max(bid, DAILY_SALARY * 0.7)

    reserve_target = 0.0
    remaining_days = max(0, 10 - day)
    if remaining_days > 0:
        reserve_target = remaining_days * DAILY_SALARY * 0.18
    max_affordable = max(0.0, budget - reserve_target)
    if max_affordable <= 0:
        max_affordable = min(budget, DAILY_SALARY * 0.35)

    bid = min(bid, budget, max_affordable)
    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.85))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Read yesterday bids for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Estimate a competitive bid based on who was most aggressive yesterday
    # Prefer Cindy if present (often highest pressure), else use overall max.
    cindy = opponents_status.get('Cindy', None)
    cindy_prev = {}
    if cindy is not None:
        cindy_prev = cindy.get('previous_trace', {}) or {}
    cindy_bid = cindy_prev.get('bid', None)

    overall_max_prev_bid = max(prev_bids) if prev_bids else 0.0
    pressure_bid = 0.0
    if cindy_bid is not None:
        try:
            pressure_bid = float(cindy_bid)
        except Exception:
            pressure_bid = 0.0
    if pressure_bid <= 0.0:
        pressure_bid = overall_max_prev_bid

    # Supply-based aggressiveness: higher supply -> can bid less; lower supply -> bid more.
    # Normalize supply in [MIN_SUPPLY, MAX_SUPPLY]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # If Cindy was aggressive yesterday, we bid just under her typical pressure to win water
    # without paying her peak.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Base target: around 0.55 salary, adjusted by pressure and supply.
    target = DAILY_SALARY * (0.55 + 0.15 * (1.0 - supply_factor))

    # Pressure adjustment: if someone bid high, increase but cap.
    # Use thresholds relative to salary.
    if pressure_bid >= DAILY_SALARY * 1.6:
        target *= 1.15
    elif pressure_bid >= DAILY_SALARY * 1.2:
        target *= 1.05
    elif pressure_bid <= DAILY_SALARY * 0.7:
        target *= 0.95

    # My HP urgency: if low HP, bid higher.
    if my_hp <= 2.0:
        target *= 1.25
    elif my_hp <= 4.0:
        target *= 1.10

    # React to yesterday max pressure: try to be slightly below it.
    if overall_max_prev_bid > 0.0:
        # Bid below max by a small margin, but not too low.
        target = min(target, overall_max_prev_bid * 0.92 + 2.0)

    # Convert target to a safe bid within budget.
    # Also ensure we don't bid tiny amounts when supply is low.
    min_bid_floor = DAILY_SALARY * (0.35 + 0.25 * (1.0 - supply_factor))
    final_bid = max(min_bid_floor, target)

    # Budget cap
    if my_budget <= 0.0:
        return 0.0
    if final_bid > my_budget:
        final_bid = my_budget

    # Final sanity: never exceed a reasonable fraction of salary
    cap = DAILY_SALARY * 2.0
    if final_bid > cap:
        final_bid = cap

    # Ensure non-negative
    if final_bid < 0.0:
        final_bid = 0.0

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    # Constants
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Extract day and supply (supply is a float, convert to int for any indexing)
    supply = int(day_context['supply'])
    day = int(day_context['day'])

    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Safe function to ensure bid does not exceed budget
    def clamp(bid):
        return max(0.0, min(bid, budget))

    # Get yesterday's max bid from alive opponents
    yesterday_max = 0.0
    for opp in opponents_status.values():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and 'bid' in prev and prev['bid'] is not None:
                yesterday_max = max(yesterday_max, prev['bid'])

    # Base target bid: if someone bid high yesterday, we may need to match or slightly beat
    # But also consider no_water_days and hp
    if no_water_days >= 1:
        # Urgent: need water to avoid HP loss
        if yesterday_max > 0:
            base = max(yesterday_max * 1.1, DAILY_SALARY * 0.8)
        else:
            base = DAILY_SALARY * 0.8
        # If hp low, be even more aggressive
        if hp <= 3:
            base = max(base, DAILY_SALARY * 0.9)
    else:
        # Not urgent, bid conservatively
        # If high competition, match yesterday's max + small increment, else bid low
        if yesterday_max > DAILY_SALARY * 0.7:
            base = max(DAILY_SALARY * 0.4, yesterday_max * 0.9)
        else:
            base = DAILY_SALARY * 0.5

    # Ensure bid stays within budget and above 0
    bid = clamp(base)
    # Final sanity: if budget is very low and we need water, bid max possible
    if no_water_days >= 2 and hp <= 2:
        bid = budget
    return bid
